import clsx from "clsx";
import "./entry-tree.css";

interface RouteLocalEntryTreeProps {
  entries: Array<{id: string; label: string}>;
  selectedId?: string;
}

export const RouteLocalEntryTree = ({entries, selectedId}: RouteLocalEntryTreeProps) => (
  <ul className={clsx("rt_entryTree_list", selectedId && "rt_entryTree_selected")}>
    {entries.map((entry) => (
      <li key={entry.id}>{entry.label}</li>
    ))}
  </ul>
);

.rt_entryTree_list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.rt_entryTree_selected {
  outline: 2px solid currentColor;
}
